using System.Data.Entity;
using StockPilot.Migrations;

namespace StockPilot.EntityFramework
{
	public class StockPilotDatabaseInitializer : MigrateDatabaseToLatestVersion<StockPilotDbContext, StockPilot.Migrations.Configuration>
	{
		public override void InitializeDatabase(StockPilotDbContext context)
		{
			base.InitializeDatabase(context);
			context.Database.ExecuteSqlCommand("\nIF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.IssueSales') AND name = N'DocumentNo' AND max_length <> 100)\n    ALTER TABLE dbo.IssueSales ALTER COLUMN DocumentNo NVARCHAR(50) NOT NULL;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Countries_Tenant_Code' AND object_id = OBJECT_ID(N'dbo.Countries')) CREATE UNIQUE INDEX UX_Countries_Tenant_Code ON dbo.Countries(TenantId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Currencies_Tenant_Code' AND object_id = OBJECT_ID(N'dbo.Currencies')) CREATE UNIQUE INDEX UX_Currencies_Tenant_Code ON dbo.Currencies(TenantId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_ItemCategories_Tenant_Code' AND object_id = OBJECT_ID(N'dbo.ItemCategories')) CREATE UNIQUE INDEX UX_ItemCategories_Tenant_Code ON dbo.ItemCategories(TenantId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_ItemMasters_Tenant_Code' AND object_id = OBJECT_ID(N'dbo.ItemMasters')) CREATE UNIQUE INDEX UX_ItemMasters_Tenant_Code ON dbo.ItemMasters(TenantId, ItemCode) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Suppliers_Tenant_Code' AND object_id = OBJECT_ID(N'dbo.Suppliers')) CREATE UNIQUE INDEX UX_Suppliers_Tenant_Code ON dbo.Suppliers(TenantId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_UnitSets_Tenant_Code' AND object_id = OBJECT_ID(N'dbo.UnitSets')) CREATE UNIQUE INDEX UX_UnitSets_Tenant_Code ON dbo.UnitSets(TenantId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_ItemSubCategories_Tenant_Category_Code' AND object_id = OBJECT_ID(N'dbo.ItemSubCategories')) CREATE UNIQUE INDEX UX_ItemSubCategories_Tenant_Category_Code ON dbo.ItemSubCategories(TenantId, ItemCategoryId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_UnitMasters_Tenant_Set_Code' AND object_id = OBJECT_ID(N'dbo.UnitMasters')) CREATE UNIQUE INDEX UX_UnitMasters_Tenant_Set_Code ON dbo.UnitMasters(TenantId, UnitSetId, Code) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_UnitConversions_Tenant_From_To' AND object_id = OBJECT_ID(N'dbo.UnitConversions')) CREATE UNIQUE INDEX UX_UnitConversions_Tenant_From_To ON dbo.UnitConversions(TenantId, FromUnitId, ToUnitId) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_PurchaseInvoices_Tenant_InvoiceNo' AND object_id = OBJECT_ID(N'dbo.PurchaseInvoices')) CREATE UNIQUE INDEX UX_PurchaseInvoices_Tenant_InvoiceNo ON dbo.PurchaseInvoices(TenantId, InvoiceNo) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_IssueSales_Tenant_DocumentNo' AND object_id = OBJECT_ID(N'dbo.IssueSales')) CREATE UNIQUE INDEX UX_IssueSales_Tenant_DocumentNo ON dbo.IssueSales(TenantId, DocumentNo) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_StockBalances_Tenant_Item' AND object_id = OBJECT_ID(N'dbo.StockBalances')) CREATE UNIQUE INDEX UX_StockBalances_Tenant_Item ON dbo.StockBalances(TenantId, ItemMasterId) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_StockMovements_Tenant_Item_Date' AND object_id = OBJECT_ID(N'dbo.StockMovements')) CREATE INDEX IX_StockMovements_Tenant_Item_Date ON dbo.StockMovements(TenantId, ItemMasterId, MovementDate) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_StockMovements_Tenant_Reference' AND object_id = OBJECT_ID(N'dbo.StockMovements')) CREATE INDEX IX_StockMovements_Tenant_Reference ON dbo.StockMovements(TenantId, ReferenceType, ReferenceId) WHERE IsDeleted = 0;\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_CurrencyConversions_Tenant_From_To_Date' AND object_id = OBJECT_ID(N'dbo.CurrencyConversions')) CREATE INDEX IX_CurrencyConversions_Tenant_From_To_Date ON dbo.CurrencyConversions(TenantId, FromCurrencyId, ToCurrencyId, EffectiveDate) WHERE IsDeleted = 0;\n");
		}
	}
}
